1	// The constructor keeps public named params distinct from the private
2	// fields they initialize, same convention `entries_repository_impl.dart`
3	// already documents.
4	// ignore_for_file: prefer_initializing_formals
5	import 'package:fpdart/fpdart.dart';
6	import 'package:hive_ce/hive_ce.dart';
7	
8	import '../../../../core/failure/failure.dart';
9	import '../../domain/entities/chat_message.dart';
10	import '../../domain/entities/chat_session.dart';
11	import '../../domain/entities/chat_stream_event.dart';
12	import '../../domain/repositories/chat_repository.dart';
13	import '../datasources/chat_remote_data_source.dart';
14	import '../models/chat_message_dto.dart';
15	import '../models/chat_session_dto.dart';
16	
17	/// On success, [listSessions]/[createSession]/[listMessages] each write
18	/// through to their own Hive box *before* returning `right(...)`, same
19	/// "persist then return" ordering `EntriesRepositoryImpl` already uses.
20	class ChatRepositoryImpl implements ChatRepository {
21	  ChatRepositoryImpl({
22	    required ChatRemoteDataSource remoteDataSource,
23	    required Box<Map> sessionsBox,
24	    required Box<Map> messagesBox,
25	  }) : _remoteDataSource = remoteDataSource,
26	       _sessionsBox = sessionsBox,
27	       _messagesBox = messagesBox;
28	
29	  final ChatRemoteDataSource _remoteDataSource;
30	  final Box<Map> _sessionsBox;
31	  final Box<Map> _messagesBox;
32	
33	  @override
34	  Future<Either<Failure, List<ChatSession>>> listSessions() async {
35	    final result = await _remoteDataSource.listSessions();
36	    return result.match(
37	      (failure) async {
38	        // `requirements.md`: "`GET /chat/sessions` — works offline
39	        // (cache)" — same cursor-null-page cache-fallback convention
40	        // `EntriesRepositoryImpl.list()` already uses; every other
41	        // `Failure` (e.g. `authExpired`) propagates as `Left`, unmapped.
42	        if (failure is NetworkOffline || failure is NetworkTimeout) {
43	          return _cachedSessions();
44	        }
45	        return left(failure);
46	      },
47	      (dtos) async {
48	        try {
49	          await _sessionsBox.putAll({
50	            for (final dto in dtos) dto.id: dto.toJson(),
51	          });
52	        } catch (error) {
53	          // A thrown Hive/disk exception must never escape unmapped
54	          // (RNF09) — same fallback `EntriesRepositoryImpl`'s own writes
55	          // already use.
56	          return left(Failure.malformedResponse(message: error.toString()));
57	        }
58	        return right(dtos.map((dto) => dto.toEntity()).toList());
59	      },
60	    );
61	  }
62	
63	  @override
64	  Future<Either<Failure, ChatSession>> createSession() async {
65	    final result = await _remoteDataSource.createSession();
66	    return result.match(
67	      // Blocked offline (`requirements.md`) — no cache fallback, unlike
68	      // [listSessions]/[listMessages]: every `Failure` propagates as
69	      // `Left`, unmapped.
70	      (failure) async => left(failure),
71	      (dto) async {
72	        // A local cache-write failure must never mask an already-
73	        // succeeded remote create: the session exists server-side
74	        // regardless, so surfacing `left(...)` here would show the user
75	        // a bootstrap error for an operation that actually succeeded
76	        // (it would simply be re-fetched via `listSessions()` next
77	        // time). Best-effort only.
78	        try {
79	          await _sessionsBox.put(dto.id, dto.toJson());
80	        } catch (_) {
81	          // Intentionally ignored — see above.
82	        }
83	        return right(dto.toEntity());
84	      },
85	    );
86	  }
87	
88	  @override
89	  Future<Either<Failure, List<ChatMessage>>> listMessages(
90	    String sessionId,
91	  ) async {
92	    final result = await _remoteDataSource.listMessages(sessionId);
93	    return result.match(
94	      (failure) async {
95	        // `requirements.md`: "`GET /chat/sessions/:id/messages` — works
96	        // offline (cache)" — same convention [listSessions] above uses.
97	        if (failure is NetworkOffline || failure is NetworkTimeout) {
98	          return _cachedMessages(sessionId);
99	        }
100	        return left(failure);
101	      },
102	      (dtos) async {
103	        try {
104	          await _messagesBox.putAll({
105	            for (final dto in dtos) dto.id: dto.toJson(),
106	          });
107	        } catch (error) {
108	          return left(Failure.malformedResponse(message: error.toString()));
109	        }
110	        return right(dtos.map((dto) => dto.toEntity()).toList());
111	      },
112	    );
113	  }
114	
115	  @override
116	  Stream<Either<Failure, ChatStreamEvent>> sendMessage(
117	    String sessionId,
118	    String content,
119	  ) =>
120	      // Design Notes: "Chat holds no local write queue" — a pure
121	      // passthrough, no Hive persistence of sent messages for this story.
122	      _remoteDataSource.sendMessage(sessionId, content);
123	
124	  /// [listSessions]'s own offline/timeout fallback — a full `chat_
125	  /// sessions` Hive box dump, sorted `updatedAt` desc (so `ChatCubit.
126	  /// init()`'s own "reuse the most recent session" pick is already
127	  /// correctly ordered even against the cache), same "always `Right`,
128	  /// even if empty" convention `EntriesRepositoryImpl._offlineFallback()`
129	  /// already uses. Each entry is decoded independently — one corrupt
130	  /// cached entry is skipped, never discarding every other (valid)
131	  /// session in the box over it.
132	  Either<Failure, List<ChatSession>> _cachedSessions() {
133	    final sessions = <ChatSession>[];
134	    for (final json in _sessionsBox.values) {
135	      try {
136	        sessions.add(
137	          ChatSessionDto.fromJson(Map<String, dynamic>.from(json)).toEntity(),
138	        );
139	      } catch (_) {
140	        // Skip this one corrupt entry — see doc above.
141	      }
142	    }
143	    sessions.sort(
144	      (a, b) => DateTime.parse(b.updatedAt).compareTo(DateTime.parse(a.updatedAt)),
145	    );
146	    return right(sessions);
147	  }
148	
149	  /// [listMessages]'s own offline/timeout fallback — a full `chat_
150	  /// messages` Hive box dump filtered to [sessionId] and sorted `seq`
151	  /// ascending (the backend's own "ordered by seq", `openapi.yaml`), same
152	  /// "always `Right`, even if empty" convention [_cachedSessions] above
153	  /// uses. Each entry is decoded independently, same corrupt-entry
154	  /// isolation as [_cachedSessions].
155	  Either<Failure, List<ChatMessage>> _cachedMessages(String sessionId) {
156	    final messages = <ChatMessage>[];
157	    for (final json in _messagesBox.values) {
158	      try {
159	        final message = ChatMessageDto.fromJson(
160	          Map<String, dynamic>.from(json),
161	        ).toEntity();
162	        if (message.sessionId == sessionId) {
163	          messages.add(message);
164	        }
165	      } catch (_) {
166	        // Skip this one corrupt entry — see doc above.
167	      }
168	    }
169	    messages.sort((a, b) => a.seq.compareTo(b.seq));
170	    return right(messages);
171	  }
172	}
