11	/// The chat feature's one remote data source — non-streaming calls go
12	/// through `ApiClient`'s plain JSON methods exactly like
13	/// `EntriesRemoteDataSource`'s own `create`/`list`/`get`; [sendMessage]
14	/// alone goes through `ApiClient.postStream` and owns the one piece of
15	/// SSE-specific logic this story introduces: splitting the raw byte
16	/// stream into `event:`/`data:` blocks and mapping each into a
17	/// [ChatStreamEvent] (or an in-band [Failure]) — kept feature-local per
18	/// the Code Map, `ApiClient` itself knows nothing about the SSE grammar.
19	class ChatRemoteDataSource {
20	  ChatRemoteDataSource(this._apiClient);
21	
22	  final ApiClient _apiClient;
23	
24	  Future<Either<Failure, List<ChatSessionDto>>> listSessions() async {
25	    final result = await _apiClient.get('chat-sessions-list');
26	    return result.flatMap((json) {
27	      try {
28	        final data = json['data'] as List<dynamic>;
29	        // Review fix: one malformed item is skipped rather than
30	        // discarding every other valid session in the response — same
31	        // per-item isolation the offline-cache fallback already applies.
32	        final dtos = <ChatSessionDto>[];
33	        for (final item in data) {
34	          try {
35	            dtos.add(ChatSessionDto.fromJson(item as Map<String, dynamic>));
36	          } catch (_) {
37	            // Skip this one malformed item.
38	          }
39	        }
40	        return right(dtos);
41	      } catch (error) {
42	        // A 200 response that doesn't match the expected shape at all
43	        // (e.g. `data` itself isn't a list) is a client-side parse
44	        // failure, never a backend-sent code — same RNF09 rationale
45	        // `EntriesRemoteDataSource`'s own calls document.
46	        return left(Failure.malformedResponse(message: error.toString()));
47	      }
48	    });
49	  }
50	
51	  /// Sends no `title` (Boundaries: "`chat-sessions-create` with no
52	  /// title") — the contract's own `title` field is optional
53	  /// (`openapi.yaml`), an empty body is valid.
54	  Future<Either<Failure, ChatSessionDto>> createSession() async {
55	    final result = await _apiClient.post('chat-sessions-create', data: const {});
56	    return result.flatMap((json) {
57	      try {
58	        final data = json['data'] as Map<String, dynamic>;
59	        return right(ChatSessionDto.fromJson(data));
60	      } catch (error) {
61	        return left(Failure.malformedResponse(message: error.toString()));
62	      }
63	    });
64	  }
65	
66	  Future<Either<Failure, List<ChatMessageDto>>> listMessages(
67	    String sessionId,
68	  ) async {
69	    final result = await _apiClient.get(
70	      'chat-messages-list',
71	      pathParams: [sessionId],
72	    );
73	    return result.flatMap((json) {
74	      try {
75	        final data = json['data'] as List<dynamic>;
76	        // Review fix: one malformed item is skipped rather than
77	        // discarding every other valid message in the response — same
78	        // per-item isolation the offline-cache fallback already applies.
79	        final dtos = <ChatMessageDto>[];
80	        for (final item in data) {
81	          try {
82	            dtos.add(ChatMessageDto.fromJson(item as Map<String, dynamic>));
83	          } catch (_) {
84	            // Skip this one malformed item.
85	          }
86	        }
87	        return right(dtos);
88	      } catch (error) {
89	        return left(Failure.malformedResponse(message: error.toString()));
90	      }
91	    });
92	  }
93	
94	  /// Consumes `ApiClient.postStream('chat-messages-send', pathParams:
95	  /// [sessionId], data: {'content': content})` chunk by chunk, buffering
96	  /// raw text until a full `\n\n`-terminated SSE event block is
97	  /// available, then hands each complete block to [_parseEvent].
98	  ///
99	  /// Terminal handling (Design Notes/I/O matrix):
100	  /// - An upstream `Left` (an offline/timeout/etc. failure from the
101	  ///   underlying HTTP call itself, surfaced by `ApiClient.postStream`) is
102	  ///   forwarded as-is and ends the stream immediately — covers "Send
103	  ///   while offline" (an immediate `Left(Failure.networkOffline)`, never
104	  ///   queued) and any other transport-level failure.
105	  /// - A parsed `done` event or an in-band `error` event (mapped via
106	  ///   [Failure.fromCode]) both end the stream right after being emitted
107	  ///   — the backend's own SSE ordering guarantees neither is followed by
108	  ///   anything else worth reading.
109	  /// - If the underlying byte stream simply ends (no exception, no
110	  ///   `done`/`error` event ever parsed) — a mid-stream drop — a single
111	  ///   trailing `Left(Failure.networkTimeout)` is emitted, since the
112	  ///   closed, 13-code taxonomy has no dedicated "dropped stream" code
113	  ///   (Design Notes).
114	  Stream<Either<Failure, ChatStreamEvent>> sendMessage(
115	    String sessionId,
116	    String content,
117	  ) async* {
118	    var buffer = '';
119	    await for (final chunkResult in _apiClient.postStream(
120	      'chat-messages-send',
121	      pathParams: [sessionId],
122	      data: {'content': content},
123	    )) {
124	      final upstreamFailure = chunkResult.fold((f) => f, (_) => null);
125	      if (upstreamFailure != null) {
126	        yield left(upstreamFailure);
127	        return;
128	      }
129	      final chunk = chunkResult.fold((_) => '', (s) => s);
130	      // Normalize after concatenation, not per-chunk — a `\r\n` line
131	      // ending split exactly across two chunks (one ends `\r`, the next
132	      // starts `\n`) would otherwise survive unnormalized in `buffer`.
133	      buffer = (buffer + chunk).replaceAll('\r\n', '\n');
134	
135	      var separatorIndex = buffer.indexOf('\n\n');
136	      while (separatorIndex != -1) {
137	        final rawEvent = buffer.substring(0, separatorIndex);
138	        buffer = buffer.substring(separatorIndex + 2);
139	        if (rawEvent.trim().isNotEmpty) {
140	          final parsed = _parseEvent(rawEvent);
141	          if (parsed != null) {
142	            final isDone = parsed.fold((_) => false, (e) => e is ChatDoneEvent);
143	            final isFailure = parsed.isLeft();
144	            yield parsed;
145	            // A `done`/in-band-error exit is a clean terminal event, not
146	            // a drop — return directly, skipping the trailing
147	            // mid-stream-drop failure below.
148	            if (isDone || isFailure) {
149	              return;
150	            }
151	          }
152	        }
153	        separatorIndex = buffer.indexOf('\n\n');
154	      }
155	    }
156	    // Reached only if the byte stream ended on its own (no exception, no
157	    // `done`/`error` event ever parsed) — a mid-stream drop.
158	    yield left(
159	      const Failure.networkTimeout(
160	        message: 'Connection closed before the response completed',
161	      ),
162	    );
163	  }
164	
165	  /// Parses one complete, blank-line-delimited SSE event block into a
166	  /// [ChatStreamEvent] (`Right`), an in-band failure (`Left`), or `null`
167	  /// when the block should simply be skipped — a `context` event
168	  /// (Boundaries: "received and discarded", never surfaced as a
169	  /// [ChatStreamEvent]) or any event name this client doesn't recognize
170	  /// (forward-compatible: an unknown future event type is ignored rather
171	  /// than treated as malformed). Any JSON-decode failure, or a decoded
172	  /// payload missing the field a known event name requires, maps to
173	  /// [Failure.malformedResponse] (Design Notes: "anything that fails to
174	  /// parse as expected becomes `Failure.malformedResponse`, never a
175	  /// crash") — never a thrown exception escaping into [sendMessage]'s own
176	  /// `async*` body.
177	  Either<Failure, ChatStreamEvent>? _parseEvent(String rawEvent) {
178	    String? eventName;
179	    final dataLines = <String>[];
180	    for (final line in rawEvent.split('\n')) {
181	      if (line.startsWith('event:')) {
182	        eventName = line.substring('event:'.length).trim();
183	      } else if (line.startsWith('data:')) {
184	        var value = line.substring('data:'.length);
185	        if (value.startsWith(' ')) {
186	          value = value.substring(1);
187	        }
188	        dataLines.add(value);
189	      }
190	    }
191	    if (eventName == null) {
192	      return null;
193	    }
194	    final dataStr = dataLines.join('\n');
195	
196	    switch (eventName) {
197	      case 'message_created':
198	        try {
199	          final json = jsonDecode(dataStr) as Map<String, dynamic>;
200	          return right(ChatMessageCreatedEvent(json['id'] as String));
201	        } catch (error) {
202	          return left(
203	            Failure.malformedResponse(
204	              message: 'malformed message_created event: $error',
205	            ),
206	          );
207	        }
208	      case 'context':
209	        // Boundaries: "never rendering the SSE `context` event's
210	        // retrieval/citation data" — received and discarded.
211	        return null;
212	      case 'token':
213	        try {
214	          final json = jsonDecode(dataStr) as Map<String, dynamic>;
215	          return right(ChatTokenEvent(json['delta'] as String));
216	        } catch (error) {
217	          return left(
218	            Failure.malformedResponse(
219	              message: 'malformed token event: $error',
220	            ),
221	          );
222	        }
223	      case 'done':
224	        return right(const ChatDoneEvent());
225	      case 'error':
226	        try {
227	          final json = jsonDecode(dataStr) as Map<String, dynamic>;
228	          final code = json['code'] as String;
229	          final message = json['message'];
230	          return left(
231	            Failure.fromCode(
232	              code,
233	              message is String ? message : 'Unknown error',
234	            ),
235	          );
236	        } catch (error) {
237	          return left(
238	            Failure.malformedResponse(
239	              message: 'malformed error event: $error',
240	            ),
241	          );
242	        }
243	      default:
244	        // Forward-compatible: an event name this client doesn't
245	        // recognize is skipped, not treated as malformed.
246	        return null;
247	    }
248	  }
249	}
