1	import 'package:hive_ce/hive_ce.dart';
2	
3	import '../../core/di/injection_container.dart';
4	import '../../core/network/api_client.dart';
5	import 'data/datasources/chat_remote_data_source.dart';
6	import 'data/repositories/chat_repository_impl.dart';
7	import 'domain/repositories/chat_repository.dart';
8	import 'presentation/cubit/chat_cubit.dart';
9	
10	/// The `chat_sessions`/`chat_messages` Hive box names — two boxes (Code
11	/// Map: "Hive box cache for `listSessions`/`listMessages`"), mirroring
12	/// `entries_injection.dart`'s `entriesBoxName` pattern but split in two
13	/// since each caches a structurally different DTO shape.
14	const chatSessionsBoxName = 'chat_sessions';
15	const chatMessagesBoxName = 'chat_messages';
16	
17	/// Registers the `chat` feature into the project's single `get_it`
18	/// instance (`sl`) — mirrors `entries_injection.dart`'s pattern. Called
19	/// from `setupCoreDependencies()` after `Hive.initFlutter()` has already
20	/// run (Code Map), same ordering requirement `registerEntriesFeature()`
21	/// documents for itself.
22	Future<void> registerChatFeature() async {
23	  final sessionsBox = await Hive.openBox<Map>(chatSessionsBoxName);
24	  final messagesBox = await Hive.openBox<Map>(chatMessagesBoxName);
25	  // `instanceName` disambiguates the two `Box<Map>` singletons from each
26	  // other and from `entries_injection.dart`'s own unnamed one — `get_it`
27	  // keys a registration by type + instance name, so three same-typed
28	  // singletons coexist safely.
29	  sl.registerSingleton<Box<Map>>(sessionsBox, instanceName: chatSessionsBoxName);
30	  sl.registerSingleton<Box<Map>>(messagesBox, instanceName: chatMessagesBoxName);
31	
32	  sl.registerLazySingleton<ChatRemoteDataSource>(
33	    () => ChatRemoteDataSource(sl<ApiClient>()),
34	  );
35	
36	  sl.registerLazySingleton<ChatRepository>(
37	    () => ChatRepositoryImpl(
38	      remoteDataSource: sl<ChatRemoteDataSource>(),
39	      sessionsBox: sl<Box<Map>>(instanceName: chatSessionsBoxName),
40	      messagesBox: sl<Box<Map>>(instanceName: chatMessagesBoxName),
41	    ),
42	  );
43	
44	  // A `lazySingleton`, not a factory (Code Map), mirroring
45	  // `MeusRegistrosCubit`: long-lived, so a session bootstrapped on one
46	  // visit to Home/Chat survives leaving and returning within the same app
47	  // session (`ChatCubit.init()`'s own no-op guard). `dispose:` wires
48	  // `close()` into `get_it`'s own reset lifecycle, same convention every
49	  // other long-lived cubit in this codebase already uses.
50	  sl.registerLazySingleton<ChatCubit>(
51	    () => ChatCubit(sl<ChatRepository>()),
52	    dispose: (cubit) => cubit.close(),
53	  );
54	}
